// connector_nodes.mjs - ONE-OFF (2026-10-29, the owner's "Close the gaps"):
// the OSM node ids of the data's frontier (section FRNT, lib/frontier.mjs) as
// shipped by road-logic-topology f7bc2f52, written to connector_nodes.json -
// the pinned list fetch_layers.mjs's "connectors" layer asks Overpass about.
// It is committed and NOT regenerated by the export: once the connectors are
// in, the frontier moves (that is the point), and a re-fetch must ask the same
// question. Re-run only to start a new list:
//   node tools/city/fetch/connector_nodes.mjs [path\to\charlotte_city.bytes]
//   (PSX_CITY_CACHE: the Overpass cache, default tools/city/cache)
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { parseCity } from '../lib/citydata.mjs';
const HERE = dirname(fileURLToPath(import.meta.url));
const CACHE = process.env.PSX_CITY_CACHE || join(HERE, '..', 'cache');
const file = process.argv[2] || join(HERE, '..', '..', '..', 'Assets', 'PSXRacing', 'Resources', 'charlotte_city.bytes');
const C = parseCity(readFileSync(file));
const LAT0 = 35.18456015184093, LON0 = -80.81770185962013, M_LAT = 111132, M_LON = 111320 * Math.cos(LAT0 * Math.PI / 180);
const toX = lon => (lon - LON0) * M_LON, toZ = lat => (lat - LAT0) * M_LAT;
const raw = new Map();
for (const f of ['ways_all.json', 'streets_core.json', 'uncc_ways.json'])
  try { for (const w of JSON.parse(readFileSync(join(CACHE, f), 'utf8')).elements) if (w.type === 'way' && w.geometry) raw.set(w.id, w); } catch { /* optional */ }
const world = [], gaps = [], miss = [];
for (let n = 0; n < C.nodes.length; n++) {
  const bits = C.frontier[n];
  if (!bits || (bits & 4 && !(bits & ~4))) continue;    // a dropped way only: our own choice, not a gap
  const p = C.nodes[n];
  let best = null, bd = 1e9;
  for (const ei of C.nodeEdges[n]) {
    const w = raw.get(C.edges[ei].wayId);
    if (!w) continue;
    w.nodes.forEach((id, k) => { const g = w.geometry[k]; const d = Math.hypot(toX(g.lon) - p.x, toZ(g.lat) - p.z); if (d < bd) { bd = d; best = id; } });
  }
  if (best === null || bd > 1) { miss.push(n); continue; }
  (bits & 1 ? world : gaps).push(best);
}
const uniq = a => [...new Set(a)].sort((x, y) => x - y);
const out = { note: 'OSM node ids of the FRNT frontier (road-logic-topology f7bc2f52): gaps = minor streets / one-ways / islands inside the beltway box (ask for the ways at each), world = roads cut at the beltway box (ask for each one\'s continuation). Pinned list - see connector_nodes.mjs.',
              source: 'charlotte_city.bytes FRNT, ' + new Date().toISOString().slice(0, 10), gaps: uniq(gaps), world: uniq(world) };
writeFileSync(join(HERE, 'connector_nodes.json'), JSON.stringify(out, null, 1) + '\n');
console.log(`gaps ${out.gaps.length}, world ${out.world.length}, unmatched ${miss.length}`);
